const L = require('lv-automation').w12;
const c = $('Classify + validate (w12.classifyOp)').first().json;
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (!r.booking_id || r.already_dispositioned) continue;
  // an Attended tap opened the broker's 24-h window (the list); a portal/console 'feedback' op uses his last inbound
  const last = c.op === 'broker_tap' ? Date.parse(c.now_iso) : (r.broker_last_inbound_at ? Date.parse(r.broker_last_inbound_at) : NaN);
  out.push({ json: L.dispositionItem(r, Date.parse(c.now_iso), last) });
}
return out;

const L = require('lv-automation').w12;
const m = $json.msg || { media: 'audio', media_id: $json.media_id };
const ref = L.voiceNoteRef(m);
return { json: { ...$json, ref, from: (m && m.from) || $json.from || null } };

const L = require('lv-automation').w12;
const now = Date.parse($('Classify + validate (w12.classifyOp)').first().json.now_iso);
return L.qualityEventItems($input.all().map((it) => it.json), now).map((x) => ({ json: x }));

const L = require('lv-automation').w12;
const now = Date.parse($('Classify + validate (w12.classifyOp)').first().json.now_iso);
const out = [];
for (const it of $input.all()) { const c = L.portalResolution(it.json, now); if (c) out.push({ json: c }); }
return out;

// lib/wa-route.cjs: "Send WhatsApp" sends through smc-whatsapp-send (WHATSAPP_PROVIDER meta | twilio). Generated: edit the
// generator / route-wa-sends.mjs config, not this node. record:false (this workflow logs the message from the returned id).
const wa = $json.send.wa;
const exec = (typeof $execution !== 'undefined' && $execution && $execution.id) || 'x';
const idx = (typeof $itemIndex !== 'undefined') ? $itemIndex : 0;
return { json: {
  kind: 'prebuilt', wa, to: wa && wa.to,
  record: false, caller: "W12", bypass_suppression: false,
  phone_number_id: null,
  lead_id: null, broker_id: null,
  correlation: "W12:Send WhatsApp:" + exec + ':' + idx,
} };
